function generateTerraformProvider(baseUrl) {
    return `terraform {
  required_providers {
    harness = {
      source  = "harness/harness"
      version = ">= 0.31.0"
    }
  }
}

provider "harness" {
  endpoint         = "${baseUrl}"
  account_id       = var.harness_account_id
  platform_api_key = var.harness_api_key
}
`;
}
function generateVariablesTf() {
    return `variable "harness_account_id" {
  description = "Harness account identifier"
  type        = string
}

variable "harness_api_key" {
  description = "Harness API key (PAT or service account token)"
  type        = string
  sensitive   = true
}

variable "org_name" {
  description = "Name of the Harness organization to create"
  type        = string
  default     = "Chaos Engineering"
}

variable "org_identifier" {
  description = "Identifier for the organization (lowercase, underscores)"
  type        = string
  default     = "chaos_engineering"
}

variable "project_name" {
  description = "Name of the Harness project to create"
  type        = string
  default     = "Chaos Onboarding"
}

variable "project_identifier" {
  description = "Identifier for the project (lowercase, underscores)"
  type        = string
  default     = "chaos_onboarding"
}

variable "delegate_selectors" {
  description = "Delegate selectors (tags) for the Kubernetes connector"
  type        = list(string)
}

variable "k8s_connector_identifier" {
  description = "Identifier for the Kubernetes connector"
  type        = string
  default     = "chaos_k8s_connector"
}

variable "k8s_connector_name" {
  description = "Display name for the Kubernetes connector"
  type        = string
  default     = "Chaos K8s Connector"
}

variable "tags" {
  description = "Tags to apply to all resources"
  type        = map(string)
  default = {
    "managed_by" = "terraform"
    "purpose"    = "chaos-onboarding"
  }
}
`;
}
function generateMainTf() {
    return `# =============================================================================
# Harness Chaos Engineering — Kubernetes Onboarding
# Generated by harness-chaos-advisor-agent
# =============================================================================

locals {
  tags_set = [for k, v in var.tags : "\${k}=\${v}"]
}

# -----------------------------------------------------------------------------
# 1. Organization
# -----------------------------------------------------------------------------
resource "harness_platform_organization" "chaos_org" {
  identifier  = var.org_identifier
  name        = var.org_name
  description = "Organization for Chaos Engineering onboarding"
  tags        = local.tags_set
}

# -----------------------------------------------------------------------------
# 2. Project
# -----------------------------------------------------------------------------
resource "harness_platform_project" "chaos_project" {
  depends_on = [harness_platform_organization.chaos_org]

  identifier  = var.project_identifier
  name        = var.project_name
  org_id      = harness_platform_organization.chaos_org.id
  description = "Project for Kubernetes chaos engineering"
  tags        = local.tags_set
}

# -----------------------------------------------------------------------------
# 3. Kubernetes Connector (delegate assume-role method)
# -----------------------------------------------------------------------------
resource "harness_platform_connector_kubernetes" "chaos_k8s" {
  depends_on = [harness_platform_project.chaos_project]

  identifier = var.k8s_connector_identifier
  name       = var.k8s_connector_name
  org_id     = harness_platform_organization.chaos_org.id
  project_id = harness_platform_project.chaos_project.id

  inherit_from_delegate {
    delegate_selectors = var.delegate_selectors
  }

  description = "Kubernetes connector for chaos engineering (inherits credentials from delegate)"
  tags        = local.tags_set
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "organization_id" {
  description = "Created organization identifier"
  value       = harness_platform_organization.chaos_org.id
}

output "project_id" {
  description = "Created project identifier"
  value       = harness_platform_project.chaos_project.id
}

output "k8s_connector_id" {
  description = "Kubernetes connector identifier"
  value       = harness_platform_connector_kubernetes.chaos_k8s.id
}
`;
}
function generateTfvarsTemplate(accountId, delegateSelectors) {
    return `# Harness Chaos Onboarding — terraform.tfvars
# Fill in your values and run: terraform init && terraform apply

harness_account_id = "${accountId}"
harness_api_key    = ""  # Set via TF_VAR_harness_api_key env var for security

# Delegate selectors (from your chosen delegate)
delegate_selectors = ${JSON.stringify(delegateSelectors)}

# Organization
org_name       = "Chaos Engineering"
org_identifier = "chaos_engineering"

# Project
project_name       = "Chaos Onboarding"
project_identifier = "chaos_onboarding"

# Kubernetes Connector
k8s_connector_name       = "Chaos K8s Connector"
k8s_connector_identifier = "chaos_k8s_connector"

tags = {
  "managed_by" = "terraform"
  "purpose"    = "chaos-onboarding"
}
`;
}
function generateDiscoveryTf() {
    return `# =============================================================================
# Service Discovery Agent — appended by harness-chaos-advisor-agent
# =============================================================================

variable "discovery_agent_name" {
  description = "Name of the service discovery agent"
  type        = string
  default     = "chaos-discovery-agent"
}

variable "discovery_org_identifier" {
  description = "Organization identifier for the discovery agent"
  type        = string
}

variable "discovery_project_identifier" {
  description = "Project identifier for the discovery agent"
  type        = string
}

variable "discovery_environment_identifier" {
  description = "Environment identifier for the discovery agent"
  type        = string
}

variable "discovery_infra_identifier" {
  description = "Infrastructure identifier for the discovery agent"
  type        = string
}

variable "discovery_namespace" {
  description = "Kubernetes namespace for service discovery"
  type        = string
  default     = "hce"
}

resource "harness_service_discovery_agent" "chaos_discovery" {
  name                   = var.discovery_agent_name
  org_identifier         = var.discovery_org_identifier
  project_identifier     = var.discovery_project_identifier
  environment_identifier = var.discovery_environment_identifier
  infra_identifier       = var.discovery_infra_identifier
  installation_type      = "CONNECTED"

  config {
    kubernetes {
      namespace = var.discovery_namespace
    }
  }
}

output "discovery_agent_name" {
  description = "Service discovery agent name"
  value       = harness_service_discovery_agent.chaos_discovery.name
}
`;
}
function generateDiscoveryTfvars(orgId, projectId, envId, infraId, namespace) {
    return `# Service Discovery Agent — terraform.tfvars (append or merge)

discovery_org_identifier         = "${orgId}"
discovery_project_identifier     = "${projectId}"
discovery_environment_identifier = "${envId}"
discovery_infra_identifier       = "${infraId}"
discovery_namespace              = "${namespace}"
discovery_agent_name             = "chaos-discovery-agent"
`;
}
// ---------------------------------------------------------------------------
// Helpers — REST API calls
// ---------------------------------------------------------------------------
async function createEnvironment(client, orgId, projectId, envName, envIdentifier, envType) {
    const yaml = `environment:
  name: ${envName}
  identifier: ${envIdentifier}
  orgIdentifier: ${orgId}
  projectIdentifier: ${projectId}
  type: ${envType}
  tags: {}`;
    const raw = await client.request({
        method: "POST",
        path: "/ng/api/environmentsV2",
        params: { orgIdentifier: orgId, projectIdentifier: projectId },
        body: { yaml },
    });
    const resp = raw;
    if (resp?.data?.environment) {
        return resp.data.environment;
    }
    throw new Error(resp?.message ?? "Failed to create environment");
}
async function createInfrastructure(client, orgId, projectId, envId, connectorRef, infraName, infraIdentifier, namespace) {
    const yaml = `infrastructureDefinition:
  name: ${infraName}
  identifier: ${infraIdentifier}
  orgIdentifier: ${orgId}
  projectIdentifier: ${projectId}
  environmentRef: ${envId}
  type: KubernetesDirect
  deploymentType: Kubernetes
  allowSimultaneousDeployments: false
  spec:
    connectorRef: ${connectorRef}
    namespace: ${namespace}
    releaseName: release-${infraIdentifier}`;
    const raw = await client.request({
        method: "POST",
        path: "/ng/api/infrastructures",
        body: { yaml },
    });
    const resp = raw;
    if (resp?.data?.infrastructure) {
        return resp.data.infrastructure;
    }
    throw new Error(resp?.message ?? "Failed to create infrastructure");
}
async function enableChaosV2(client, orgId, projectId, envId, infraIdentifier, infraName, namespace, serviceAccount) {
    const raw = await client.request({
        method: "POST",
        path: "/gateway/chaos/manager/api/rest/v2/infrastructure",
        body: {
            identity: infraIdentifier,
            name: infraName,
            orgIdentifier: orgId,
            projectIdentifier: projectId,
            environmentID: envId,
            namespace,
            serviceAccount,
            infraType: "KubernetesV2",
        },
    });
    const resp = raw;
    if (resp?.identity) {
        return {
            identity: resp.identity,
            token: resp.token ?? "",
            uniqueId: resp.uniqueId ?? "",
        };
    }
    throw new Error(resp?.message ?? "Failed to enable Chaos v2 infrastructure");
}
